// Cargar combobox de vistas activas
var combobox = theRoot.dataView().control("VIS_ACT");
combobox.addItem("Apuntes", "A");
combobox.addItem("Cobros", "C");
combobox.addItem("Pagos", "P");

// Leer el valor seleccionado
var formulario = theRoot.dataView();
var combobox   = formulario.control("VIS_ACT");
theRoot.setVar("VIS_ACT", combobox.itemData(combobox.currentIndex));
formulario.updateControls();
